const raw = $input.item.json;
let payload;
try {
  payload = typeof raw.message === 'string' ? JSON.parse(raw.message) : (raw.message || raw);
} catch (e) {
  return [{ json: { stored: false, error: e.message } }];
}

const readings = payload.readings || [];
const tempDS  = readings.find(r => r.sensor === 'ds18b20' && r.type === 'temperature');
const tempBME = readings.find(r => (r.sensor === 'bme280' || r.sensor === 'bmp280') && r.type === 'temperature');
const hum  = readings.find(r => r.type === 'humidity');
const pres = readings.find(r => r.type === 'pressure');

const tDS  = tempDS  ? tempDS.value  : null;
const tBME = tempBME ? tempBME.value : null;
const avgTemp = (tDS !== null && tBME !== null) ? (tDS + tBME) / 2
              : (tDS !== null ? tDS : tBME);
const drift = (tDS !== null && tBME !== null)
  ? parseFloat(Math.abs(tDS - tBME).toFixed(2)) : null;

const globalData = $getWorkflowStaticData('global');
if (!Array.isArray(globalData.readings)) globalData.readings = [];

globalData.readings.push({
  ts:                payload.timestamp || new Date().toISOString(),
  avg_temp:          avgTemp !== null ? parseFloat(avgTemp.toFixed(2)) : null,
  temp_drift:        drift,
  humidity:          hum  ? hum.value  : null,
  pressure:          pres ? pres.value : null,
  rssi:              payload.rssi       ?? null,
  status:            payload.status     || 'unknown',
  is_invalid:        payload.status === 'invalid_reading' ? 1 : 0,
  has_drift_anomaly: (drift !== null && drift > 2.0) ? 1 : 0
});

// Rolling 1-hour window at 10 s publish interval = 360 readings
if (globalData.readings.length > 360) {
  globalData.readings = globalData.readings.slice(-360);
}

globalData.last_device_id = payload.device_id || 'unknown';
globalData.last_site      = payload.site       || 'unknown';
globalData.last_fw        = payload.fw_version || 'N/A';
globalData.last_rssi      = payload.rssi       ?? null;

return [{ json: {
  stored: true,
  total_readings: globalData.readings.length
}}];

const globalData = $getWorkflowStaticData('global');
const readings = globalData.readings || [];

if (readings.length === 0) {
  return [{ json: { has_data: false } }];
}

const nonNull = (key) => readings.map(r => r[key]).filter(v => v !== null && !isNaN(v));
const avg = arr => arr.length ? arr.reduce((a, b) => a + b, 0) / arr.length : null;
const min = arr => arr.length ? Math.min(...arr) : null;
const max = arr => arr.length ? Math.max(...arr) : null;
const fmt2 = v => v !== null ? parseFloat(v.toFixed(2)) : null;
const fmt1 = v => v !== null ? parseFloat(v.toFixed(1)) : null;
const fmtInt = v => v !== null ? Math.round(v) : null;

const temps  = nonNull('avg_temp');
const hums   = nonNull('humidity');
const press  = nonNull('pressure');
const rssis  = nonNull('rssi');
const drifts = nonNull('temp_drift');

const invalidCount     = readings.reduce((s, r) => s + (r.is_invalid        || 0), 0);
const driftAnomalyCount = readings.reduce((s, r) => s + (r.has_drift_anomaly || 0), 0);
const dataQuality = parseFloat(((1 - invalidCount / readings.length) * 100).toFixed(1));

return [{ json: {
  has_data:      true,
  device_id:     globalData.last_device_id || 'unknown',
  site:          globalData.last_site      || 'unknown',
  fw_version:    globalData.last_fw        || 'N/A',
  report_time:   new Date().toISOString(),
  period_start:  readings[0].ts,
  period_end:    readings[readings.length - 1].ts,
  total_readings: readings.length,
  kpis: {
    temperature: {
      avg: fmt2(avg(temps)),
      min: fmt2(min(temps)),
      max: fmt2(max(temps))
    },
    humidity: {
      avg: fmt1(avg(hums)),
      min: fmt1(min(hums)),
      max: fmt1(max(hums))
    },
    pressure: {
      avg: fmt1(avg(press)),
      min: fmt1(min(press)),
      max: fmt1(max(press))
    },
    temp_drift: {
      avg: fmt2(avg(drifts)),
      max: fmt2(max(drifts))
    },
    rssi: {
      avg: fmtInt(avg(rssis)),
      min: min(rssis),
      max: max(rssis)
    },
    data_quality_pct:     dataQuality,
    invalid_readings:     invalidCount,
    drift_anomaly_events: driftAnomalyCount
  }
}}];

const d   = $input.item.json;
const kpi = d.kpis;

const qColor = kpi.data_quality_pct >= 95 ? '#2e7d32'
             : kpi.data_quality_pct >= 80 ? '#e65100' : '#c62828';
const qIcon  = kpi.data_quality_pct >= 95 ? '\u2705'
             : kpi.data_quality_pct >= 80 ? '\u26a0\ufe0f' : '\ud83d\udd34';

const durationMin = Math.round(d.total_readings * 10 / 60);

const reportDate = new Date(d.report_time);
const dateStr = reportDate.toLocaleDateString('en-GB', { day:'2-digit', month:'short', year:'numeric' });
const timeStr = reportDate.toLocaleTimeString('en-GB', { hour:'2-digit', minute:'2-digit' });

const statCard = (value, label, color) =>
  '<div style=\'flex:1;min-width:140px;background:#fff;border:1px solid #e9ecef;border-radius:8px;padding:16px;text-align:center;box-shadow:0 1px 4px rgba(0,0,0,.06)\'>' +
    '<div style=\'font-size:26px;font-weight:700;color:' + color + '\'>' + value + '</div>' +
    '<div style=\'font-size:11px;color:#6c757d;margin-top:4px;text-transform:uppercase;letter-spacing:.4px\'>' + label + '</div>' +
  '</div>';

const kpiRow = (label, avg, min, max, unit, warn) => {
  const warnStyle = warn ? 'color:#c62828;font-weight:700' : 'color:#212529';
  const fmt = v => v !== null ? v + ' ' + unit : '<span style=\'color:#adb5bd\'>N/A</span>';
  return '<tr>' +
    '<td style=\'padding:9px 14px;color:#6c757d;border-bottom:1px solid #f0f0f0;font-size:13px\'>' + label + '</td>' +
    '<td style=\'padding:9px 14px;border-bottom:1px solid #f0f0f0;font-size:13px;' + warnStyle + '\'>' + fmt(avg) + '</td>' +
    '<td style=\'padding:9px 14px;border-bottom:1px solid #f0f0f0;font-size:13px\'>' + fmt(min) + '</td>' +
    '<td style=\'padding:9px 14px;border-bottom:1px solid #f0f0f0;font-size:13px\'>' + fmt(max) + '</td>' +
  '</tr>';
};

const tempWarn = (kpi.temperature.max !== null && kpi.temperature.max > 40)
             || (kpi.temperature.min !== null && kpi.temperature.min < 5);
const humWarn  = (kpi.humidity.max   !== null && kpi.humidity.max   > 80)
             || (kpi.humidity.min    !== null && kpi.humidity.min    < 20);
const presWarn = (kpi.pressure.min   !== null && kpi.pressure.min   < 950)
             || (kpi.pressure.max    !== null && kpi.pressure.max   > 1060);
const driftWarn = kpi.temp_drift.max  !== null && kpi.temp_drift.max  > 2.0;
const rssiWarn  = kpi.rssi.min        !== null && kpi.rssi.min        < -80;

const html =
  '<!DOCTYPE html><html><body style=\'font-family:Arial,sans-serif;background:#f0f2f5;margin:0;padding:20px\'>' +
  '<div style=\'max-width:720px;margin:0 auto;background:#f8f9fa;border-radius:10px;overflow:hidden;box-shadow:0 4px 16px rgba(0,0,0,.12)\'>' +

  '<div style=\'background:linear-gradient(135deg,#0d3b6e,#1565c0);padding:28px 32px\'>' +
    '<h1 style=\'color:#fff;margin:0;font-size:20px;letter-spacing:.3px\'>\ud83d\udcca Re\u00b7Tech Fusion \u2014 KPI Summary Report</h1>' +
    '<p style=\'color:#90caf9;margin:6px 0 0;font-size:12px\'>' + d.device_id + ' \u00b7 ' + d.site + ' \u00b7 ' + dateStr + ' ' + timeStr + ' UTC</p>' +
  '</div>' +

  '<div style=\'padding:28px 32px;background:#fff\'>' +

    '<div style=\'display:flex;gap:12px;margin-bottom:28px;flex-wrap:wrap\'>' +
      statCard(d.total_readings, 'Readings (' + durationMin + ' min)', '#1565c0') +
      statCard(kpi.data_quality_pct + '%', qIcon + ' Data Quality', qColor) +
      statCard(kpi.drift_anomaly_events, 'Drift Events (>2\u00b0C)', kpi.drift_anomaly_events > 0 ? '#e65100' : '#2e7d32') +
      statCard(kpi.invalid_readings, 'Invalid Readings', kpi.invalid_readings > 0 ? '#c62828' : '#2e7d32') +
    '</div>' +

    '<table style=\'width:100%;border-collapse:collapse\'>' +
      '<thead><tr style=\'background:#f8f9fa\'>' +
        '<th style=\'padding:10px 14px;text-align:left;border-bottom:2px solid #dee2e6;font-size:11px;text-transform:uppercase;color:#6c757d;letter-spacing:.5px\'>Metric</th>' +
        '<th style=\'padding:10px 14px;text-align:left;border-bottom:2px solid #dee2e6;font-size:11px;text-transform:uppercase;color:#6c757d;letter-spacing:.5px\'>Average</th>' +
        '<th style=\'padding:10px 14px;text-align:left;border-bottom:2px solid #dee2e6;font-size:11px;text-transform:uppercase;color:#6c757d;letter-spacing:.5px\'>Min</th>' +
        '<th style=\'padding:10px 14px;text-align:left;border-bottom:2px solid #dee2e6;font-size:11px;text-transform:uppercase;color:#6c757d;letter-spacing:.5px\'>Max</th>' +
      '</tr></thead>' +
      '<tbody>' +
        kpiRow('Temperature',             kpi.temperature.avg, kpi.temperature.min, kpi.temperature.max, '\u00b0C',  tempWarn)  +
        kpiRow('Humidity',                kpi.humidity.avg,    kpi.humidity.min,    kpi.humidity.max,    '%',        humWarn)   +
        kpiRow('Pressure',                kpi.pressure.avg,    kpi.pressure.min,    kpi.pressure.max,    'hPa',      presWarn)  +
        kpiRow('Temp Drift (cross-sensor)',kpi.temp_drift.avg,  null,               kpi.temp_drift.max,  '\u00b0C',  driftWarn) +
        kpiRow('Wi-Fi RSSI',              kpi.rssi.avg,        kpi.rssi.min,        kpi.rssi.max,        'dBm',      rssiWarn)  +
      '</tbody>' +
    '</table>' +

    '<div style=\'margin-top:20px;padding:12px 16px;background:#f8f9fa;border-radius:6px;font-size:12px;color:#6c757d;border:1px solid #e9ecef\'>' +
      '<strong>Report period:</strong> ' + d.period_start + ' \u2192 ' + d.period_end +
      '<br><strong>Firmware:</strong> ' + d.fw_version +
    '</div>' +

  '</div>' +
  '<div style=\'background:#f8f9fa;padding:16px 32px;text-align:center;font-size:11px;color:#adb5bd;border-top:1px solid #dee2e6\'>' +
    'Re\u00b7Tech Fusion IoT Platform \u00b7 INSAT, University of Carthage \u00b7 Automated KPI Report' +
  '</div>' +
  '</div></body></html>';

return [{ json: {
  ...d,
  email_subject: '[KPI Report] ' + d.device_id + ' @ ' + d.site + ' \u2014 ' + dateStr + ' ' + timeStr + ' UTC',
  email_html: html
}}];
